    ["Fenêtre du personnage (touche C) : équipement, niveau d'objet, réputation, compétences, monnaies."] = "Finestra del personaggio (tasto C): equipaggiamento, livello oggetto, reputazione, abilità, valute.",
    ["Fenêtres"] = "Finestre",
    ["Ferme la fenêtre (Échap marche aussi)."] = "Chiude la finestra (funziona anche Esc).",
    ["Fermer"] = "Chiudi",
    ["Fine (jeu)"] = "Sottile (gioco)",
    ["Fluidité de l'affichage. Vert : 50 et plus, orange : 25 à 49, rouge : moins de 25."] = "Fluidità della visualizzazione. Verde: 50 e oltre, arancione: da 25 a 49, rosso: meno di 25.",
    ["Fluidité du jeu (images par seconde)."] = "Fluidità del gioco (fotogrammi al secondo).",
    ["Flux Platyplus - glisse-moi"] = "Feed Platyplus - trascinami",
    ["Flux de butin"] = "Feed del bottino",
    ["Flux de butin à l'écran"] = "Flusso del bottino sullo schermo",
    ["Flux à l'écran"] = "Flusso sullo schermo",
    ["Flèches haut / bas : ce que tu as tapé"] = "Frecce su / giù: ciò che hai digitato",
    ["Focalisation"] = "Focalizzazione",
    ["Folie"] = "Follia",
    ["Fond uni sans les bords arrondis (sa couleur et sa transparence restent celles réglées dans le jeu), onglets plats avec un trait bleu sous celui qui est actif, zone de saisie sombre bordée de bleu. Coupé : le chat redevient exactement comme avant."] = "Sfondo uniforme senza i bordi arrotondati (il colore e la trasparenza restano quelli impostati nel gioco), schede piatte con una linea blu sotto quella attiva, casella di testo scura bordata di blu. Disattivo: la chat torna esattamente come prima.",
    ["Fond uni, onglets plats, zone de saisie sombre."] = "Sfondo uniforme, schede piatte, casella di testo scura.",
    ["Fond, bord et coins arrondis comme réglés dans la carte « Cadre »."] = "Sfondo, bordo e angoli arrotondati come impostati nella scheda «Riquadro».",
    ["Format"] = "Formato",
    ["Fragments d'âme"] = "Frammenti d'anima",
    ["Fulgurance, Vengeance, Exécution, Ivresse de la victoire"] = "Sopraffazione, Vendetta, Esecuzione, Impeto della vittoria",
    ["Fureur"] = "Furia",
    ["Gagné par %s"] = "Vinto da %s",
    ["Gagnée cette session"] = "Guadagnato in questa sessione",
    ["Garde l'étincelle de butin du jeu allumée."] = "Mantiene acceso il bagliore del bottino del gioco.",
    ["Garder les apparences que je n'ai pas"] = "Mantieni gli aspetti che non ho",
    ["Garder les derniers messages"] = "Conserva gli ultimi messaggi",
    ["Gardé pour ce personnage"] = "Conservato per questo personaggio",
    ["Glisse ici un objet de tes sacs"] = "Rilascia qui un oggetto delle tue borse",
    ["Glisse ici un sort de ton grimoire"] = "Rilascia qui un incantesimo del tuo libro degli incantesimi",
    ["Gris"] = "Grigio",
    ["Gris : %d"] = "Grigio: %d",
    ["Groupe"] = "Gruppo",
    ["Groupe (%d)"] = "Gruppo (%d)",
    ["Groupes, duels et invocations"] = "Gruppi, duelli ed evocazioni",
    ["Groupes, duels et invocations acceptés ou refusés pour toi ; une interface plus calme."] = "Gruppi, duelli ed evocazioni accettati o rifiutati al posto tuo; un'interfaccia più tranquilla.",
    ["Guerrier"] = "Guerriero",
    ["Guerrier : Fulgurance, Vengeance, Exécution, Ivresse de la victoire. Voleur : Riposte. Chasseur : Contre-attaque, Morsure de la mangouste, Ordre de tuer. Paladin : Marteau de courroux. Exemple : tu pares un coup, Riposte apparaît avec sa touche. Coupé, ces sorts ne sont plus annoncés (sauf s'ils brillent et que « Sorts qui brillent » est actif)."] = "Guerriero: Sopraffazione, Vendetta, Esecuzione, Impeto della vittoria. Ladro: Risposta. Cacciatore: Contrattacco, Morso della mangusta, Comando di uccisione. Paladino: Martello dell'ira. Esempio: pari un colpo, Risposta appare con il suo tasto. Disattivo, questi incantesimi non vengono più annunciati (a meno che brillino e «Incantesimi che brillano» sia attivo).",
    ["Guerrier : une petite icône quand le buff est actif."] = "Guerriero: una piccola icona mentre il potenziamento è attivo.",
    ["Guilde"] = "Gilda",
    ["HDV"] = "Casa d'aste",
    ["HDV : %s ne sera plus proposé (/pp hdv exclus pour la liste)"] = "Casa d'aste: %s non verrà più proposto (/pp hdv exclus per l'elenco)",
    ["HDV : %s refusé"] = "Casa d'aste: %s rifiutato",
    ["HDV : %s refusé (%s)"] = "Casa d'aste: %s rifiutato (%s)",
    ["HDV : coche d'abord les objets à mettre en vente (clic sur la ligne)"] = "Casa d'aste: seleziona prima gli oggetti da mettere in vendita (clic sulla riga)",
    ["HDV : le jeu demande une confirmation pour %s. Clique encore (ou ta touche) pour confirmer."] = "Casa d'aste: il gioco chiede una conferma per %s. Clicca ancora (o il tuo tasto) per confermare.",
    ["HDV : le scan complet n'a rien renvoyé."] = "Casa d'aste: la scansione completa non ha restituito nulla.",
    ["HDV : le serveur n'autorise un scan complet que toutes les 15 min, réessaie dans %d min."] = "Casa d'aste: il server permette una scansione completa solo ogni 15 min, riprova tra %d min.",
    ["HDV : pas de réponse au scan complet, réessaie plus tard."] = "Casa d'aste: nessuna risposta alla scansione completa, riprova più tardi.",
    ["HDV : prix trouvés."] = "Casa d'aste: prezzi trovati.",
    ["HDV : recherche des prix en cours, patiente un instant"] = "Casa d'aste: ricerca dei prezzi in corso, attendi un attimo",
    ["HDV : rien de prêt à mettre en vente"] = "Casa d'aste: niente di pronto da mettere in vendita",
    ["HDV : scan complet lancé (tous les prix de l'HDV, quelques secondes)..."] = "Casa d'aste: scansione completa avviata (tutti i prezzi della Casa d'aste, qualche secondo)...",
    ["HDV : scan complet refusé par le jeu"] = "Casa d'aste: scansione completa rifiutata dal gioco",
    ["HDV : scan complet terminé, %d objet(s) avec un prix."] = "Casa d'aste: scansione completa terminata, %d oggetto/i con un prezzo.",
    ["Hauteur de la barre"] = "Altezza della barra",
    ["Healer suivi"] = "Guaritore seguito",
    ["Histoire de la quête"] = "Storia della missione",
    ["Hors combat"] = "Fuori combattimento",
    ["Hors combat : boit la boisson la plus haute (eau, jus...) pour la mana. En combat : boit ta meilleure potion de mana. Remettre « aucune » coupe la touche."] = "Fuori combattimento: beve la bevanda migliore (acqua, succo...) per il mana. In combattimento: beve la tua migliore pozione di mana. Rimettere «nessuno» disattiva il tasto.",
    ["Hors combat : l'icône du buff manquant avec le nom de l'allié."] = "Fuori combattimento: l'icona del potenziamento mancante con il nome dell'alleato.",
    ["Hors combat : l'icône du buff qui te manque et le nom de l'allié qui peut te le donner."] = "Fuori combattimento: l'icona del buff che ti manca e il nome dell'alleato che può dartelo.",
    ["Hors combat : mange la nourriture la plus haute que tu peux utiliser. En combat : boit ta meilleure potion de soins. « La plus haute » = niveau requis, puis niveau de l'objet. Remettre « aucune » coupe la touche."] = "Fuori combattimento: mangia il cibo migliore che puoi usare. In combattimento: beve la tua migliore pozione di cura. «Migliore» = livello richiesto, poi livello dell'oggetto. Rimettere «nessuno» disattiva il tasto.",
    ["Hors combat · quête · rare"] = "Fuori combattimento - missione - raro",
    ["Hostile"] = "Ostile",
    ["Hôtel des ventes"] = "Casa d'aste",
    ["ID d'objet ou lien, puis Entrée"] = "ID oggetto o link, poi Invio",
    ["Icône & infos"] = "Icona e info",
    ["Icône Platyplus"] = "Icona Platyplus",
    ["Icône de Maîtrise du blocage"] = "Icona di Blocco con scudo",
    ["Icônes"] = "Icone",
    ["Il n'est pas sur ta liste de menace"] = "Non è nella tua lista di minaccia",
    ["Il ne t'attaque que si tu le tapes."] = "Ti attacca solo se lo colpisci.",
    ["Il ne te tape pas"] = "Non ti sta colpendo",
    ["Il t'a échappé"] = "Ti è sfuggito",
    ["Il tape un allié"] = "Colpisce un alleato",
    ["Il te manque encore des objets ou des objectifs."] = "Ti mancano ancora oggetti o obiettivi.",
    ["Il te tape"] = "Colpisce te",
    ["Images par seconde"] = "Fotogrammi al secondo",
    ["Immersif"] = "Immersivo",
    ["Immobilise"] = "Immobilizza",
    ["Incantations"] = "Lanci",
    ["Inclure les objets « lié quand équipé »"] = "Includi gli oggetti «vincolato all'equipaggiamento»",
    ["Inhabituel"] = "Non comune",
    ["Interaction rapide"] = "Interazione rapida",
    ["Interagit avec ce que tu survoles, sinon avec la cible la plus proche."] = "Interagisce con ciò che sorvoli, altrimenti con il bersaglio più vicino.",
    ["Interface"] = "Interfaccia",
    ["Interface et caméra"] = "Interfaccia e telecamera",
    ["Interruptible"] = "Interrompibile",
    ["Inutilisable"] = "Inutilizzabile",
    ["Jamais moins que le marchand"] = "Mai meno del mercante",
    ["Je joue"] = "Gioco come",
    ["Jets /roll"] = "Tiri /roll",
    ["Jets de butin"] = "Tiri del bottino",
    ["Jets de dés en groupe"] = "Tiri di dado di gruppo",
    ["Jets en cours"] = "Tiri in corso",
    ["Jeu"] = "Gioco",
    ["Joue un avertissement quand l'alerte se déclenche. Hors combat, pas de son : un healer qui boit est à sec exprès. Le bouton « Aperçu » le fait entendre."] = "Emette un avviso sonoro quando scatta l'allarme. Fuori combattimento niente suono: un guaritore che beve è a secco di proposito. Il pulsante «Anteprima» te lo fa sentire.",
    ["Jouer"] = "Gioca",
    ["Journal des donjons"] = "Diario dei dungeon",
    ["L'HDV garde 5 % de chaque vente. Exemple : minerai à 18 pc à l'HDV, il te reste 17 pc, contre 5 pc chez le marchand : il est mis en vente. À 5 pc à l'HDV, il ne te resterait que 4 pc : il est marqué « marchand mieux » et reste dans tes sacs."] = "La casa d'aste trattiene il 5 % di ogni vendita. Esempio: minerale a 18 pc alla casa d'aste, te ne restano 17 pc, contro 5 pc dal mercante: viene messo in vendita. A 5 pc alla casa d'aste te ne resterebbero solo 4 pc: è segnato «meglio il mercante» e resta nelle tue borse.",
    ["L'addon DungeonJournal séparé est activé : c'est lui qui tourne, avec la liste des donjons, « À ton niveau » et le style de Platyplus posés dessus. Le journal intégré à Platyplus reste éteint et garde une copie de ses réglages, de tes favoris et de ta progression : désactive DungeonJournal dans la liste des addons (écran de choix du personnage) puis relance le jeu pour revenir au journal intégré."] = "L'addon DungeonJournal separato è attivo: è lui a funzionare, con l'elenco dei dungeon, «Al tuo livello» e lo stile di Platyplus applicati sopra. Il diario integrato in Platyplus resta spento e conserva una copia delle sue impostazioni, dei tuoi preferiti e dei tuoi progressi: disattiva DungeonJournal nell'elenco degli addon (schermata di selezione del personaggio) e riavvia il gioco per tornare al diario integrato.",
    ["L'alerte apparaît quand le sort est vraiment utilisable (bonne posture, assez de rage, pas en recharge) et disparaît dès qu'il ne l'est plus. La touche est celle du bouton où tu as rangé le sort : un sort absent de tes barres n'est pas annoncé. Choisis les sorts surveillés dans la carte du dessous. /pp proc liste tes sorts surveillés et leur touche."] = "L'avviso appare quando l'incantesimo è davvero utilizzabile (postura giusta, abbastanza rabbia, non in recupero) e scompare appena non lo è più. Il tasto è quello del pulsante dove hai messo l'incantesimo: un incantesimo assente dalle tue barre non viene segnalato. Scegli gli incantesimi monitorati nella scheda qui sotto. /pp proc elenca i tuoi incantesimi monitorati e il loro tasto.",
    ["L'alerte quand une technique devient utilisable (Fulgurance, Riposte…) : quoi surveiller, comment l'afficher."] = "L'avviso quando una tecnica diventa utilizzabile (Sopraffazione, Riposte…): cosa controllare, come mostrarlo.",
    ["L'alerte se déclenche quand il te reste ce nombre d'emplacements libres, ou moins."] = "L'avviso scatta quando ti restano questo numero di slot liberi, o meno.",
    ["L'argent de ce personnage."] = "Il denaro di questo personaggio.",
    ["L'aspect de la barre colorée. Unie = couleur plate, sans reflet."] = "L'aspetto della barra colorata. Uniforme = colore piatto, senza riflesso.",
    ["L'heure devant chaque message"] = "L'ora davanti a ogni messaggio",
    ["L'icône Platyplus"] = "L'icona di Platyplus",
    ["L'icône Platyplus et sa barre d'infos, où tu veux à l'écran."] = "L'icona Platyplus e la sua barra informazioni, dove vuoi sullo schermo.",
    ["L'icône du sort qui vient de devenir utilisable, sous ton personnage, avec la touche à presser."] = "L'icona dell'incantesimo appena diventato utilizzabile, sotto il tuo personaggio, con il tasto da premere.",
    ["L'étincelle du jeu oublie certains cadavres, les boss notamment. Une fois le combat fini, un cadavre qui a encore du butin pour toi brille quand tu t'en approches. Elle dit seulement « il reste du butin », pas quoi. Le jeu pose alors sa plaque de nom (nom et barre de vie) sur ce cadavre : c'est elle qui porte l'étincelle. Utilise le ciblage d'interaction du jeu : l'objet le plus proche, jusqu'à environ 15 m, tout autour de toi. Pour cela Platyplus allume « Activer la touche d'interaction » et les icônes d'interaction des objets du monde du jeu, et les remet comme avant quand tu coupes toutes les étincelles ci-dessous. Pas d'étincelle pendant un combat."] = "Il bagliore del gioco dimentica certi cadaveri, in particolare i boss. A fine combattimento, un cadavere che ha ancora del bottino per te brilla quando ti avvicini. Dice solo «resta del bottino», non cosa. Il gioco mette allora la sua targhetta (nome e barra della salute) su quel cadavere: è lei a portare il bagliore. Usa il bersaglio di interazione del gioco: l'oggetto più vicino, fino a circa 15 m, tutto intorno a te. Per questo Platyplus attiva «Attiva il tasto di interazione» e le icone di interazione degli oggetti del mondo del gioco, e le rimette come prima quando disattivi tutti i bagliori qui sotto. Nessun bagliore durante il combattimento.",
    ["La barre de sort sous la plate d'un mob qui incante."] = "La barra di lancio sotto la targhetta di un mob che lancia un incantesimo.",
    ["La fenêtre de réglages du journal lui-même : bouton de la minicarte, infobulles des objets, quêtes de classe et de métier, mode RPG... (aussi : /dj options)."] = "La finestra delle impostazioni del diario stesso: pulsante della minimappa, descrizioni degli oggetti, missioni di classe e di professione, modalità GDR... (anche: /dj options).",
    ["La langue du message envoyé (le menu reste en français). En anglais, avec les abréviations des joueurs : « Hi, could I get BoK pls? Thanks :) » (Fort, MotW, Int…) ; « Tous ses buffs » : « Hi, could I get buff pls? Thanks :) »."] = "La lingua del messaggio inviato (il menu resta in francese). In inglese, con le abbreviazioni dei giocatori: «Hi, could I get BoK pls? Thanks :)» (Fort, MotW, Int…); «Tutti i suoi potenziamenti»: «Hi, could I get buff pls? Thanks :)».",
    ["La menace d'un coup d'œil"] = "La minaccia a colpo d'occhio",
    ["La repérer au milieu d'un pack."] = "Individuarla in mezzo a un branco.",
    ["La touche"] = "Il tasto",
    ["La touche choisie interagit d'abord avec ce que la souris survole, sinon avec la cible d'interaction la plus proche : PNJ, coffre, plante, cadavre à dépouiller. Coupée, Platyplus ne lie plus aucune touche."] = "Il tasto scelto interagisce prima con ciò che il mouse sorvola, altrimenti con il bersaglio di interazione più vicino: PNG, forziere, erba, cadavere da scuoiare. Se disattivato, Platyplus non assegna più alcun tasto.",
    ["La touche à presser, en gros sous l'icône (« 3 », « Maj+E »)."] = "Il tasto da premere, in grande sotto l'icona («3», «Maiusc+E»).",
    ["Laisser le jeu choisir"] = "Lascia scegliere al gioco",
    ["Lancer les sorts à l'appui de la touche"] = "Lancia gli incantesimi alla pressione del tasto",
    ["Langue"] = "Lingua",
    ["Langue changée. Les textes déjà affichés ailleurs (barre d'infos, options du jeu) suivront au prochain /reload."] = "Lingua cambiata. I testi già mostrati altrove (barra informazioni, opzioni del gioco) seguiranno al prossimo /reload.",
    ["Langue de Platyplus"] = "Lingua di Platyplus",
    ["Langue de la demande"] = "Lingua della richiesta",
    ["Langue des textes de Platyplus. Les textes pas encore traduits restent en anglais, ou en français à défaut."] = "Lingua dei testi di Platyplus. I testi non ancora tradotti restano in inglese, o in francese in mancanza.",
    ["Largeur"] = "Larghezza",
    ["Largeur de la barre de coups blancs."] = "Larghezza della barra dei colpi bianchi.",
    ["Largeur de la barre, en points d'interface."] = "Larghezza della barra, in punti dell'interfaccia.",
    ["Latence"] = "Latenza",
    ["Le bord de la plate de ta cible est plus épais et de la couleur choisie."] = "Il bordo della targhetta del tuo bersaglio è più spesso e del colore scelto.",
    ["Le butin sans clics"] = "Il bottino senza clic",
    ["Le choix est gardé tout de suite, mais les fenêtres déjà construites gardent l'ancienne langue : recharge l'interface (bouton ci-dessous ou /reload)."] = "La scelta viene salvata subito, ma le finestre già costruite mantengono la vecchia lingua: ricarica l'interfaccia (pulsante qui sotto o /reload).",
    ["Le clignotement fait toujours trois éclats, plus ou moins vite."] = "Il lampeggio fa sempre tre bagliori, più o meno veloci.",
    ["Le confort tout-en-un"] = "Il comfort tutto in uno",
    ["Le confort tout-en-un pour WoW Forever · v%s"] = "Il comfort tutto in uno per WoW Forever · v%s",
    ["Le confort tout-en-un · v%s"] = "Il comfort tutto in uno · v%s",
    ["Le contour et le fond autour de la barre."] = "Il contorno e lo sfondo intorno alla barra.",
    ["Le fond visible là où le mob a perdu de la vie. 0 % = transparent."] = "Lo sfondo visibile dove il mob ha perso salute. 0 % = trasparente.",
    ["Le gros cadre sombre du jeu remplacé par le nôtre, réglable ci-dessous."] = "Il grosso riquadro scuro del gioco sostituito dal nostro, regolabile qui sotto.",
    ["Le healer est celui que le groupe désigne comme soigneur (file de donjon, ou rôle donné par le chef de groupe). Si personne n'a ce rôle, cible ton healer et clique « Mon healer = ma cible ». S'il y a plusieurs soigneurs, la barre suit le premier de la liste du groupe : choisis le tien avec le bouton."] = "Il guaritore è quello che il gruppo indica come curatore (coda dei dungeon, o ruolo dato dal capogruppo). Se nessuno ha questo ruolo, seleziona il tuo guaritore e clicca «Il mio guaritore = il mio bersaglio». Se ci sono più curatori, la barra segue il primo dell'elenco del gruppo: scegli il tuo con il pulsante.",
    ["Le jeu fait briller les objets de quête à ramasser (une caisse, une torche par terre...), mais un préréglage graphique coupe cette étincelle. Platyplus la remet à la connexion et juste après chaque changement graphique. Ton mode de contour (outline) n'est pas touché. Couper cette option ne prend effet qu'après un redémarrage du jeu : /reload ne suffit pas."] = "Il gioco fa brillare gli oggetti di missione da raccogliere (una cassa, una torcia a terra...), ma un'impostazione grafica predefinita disattiva questo bagliore. Platyplus lo riattiva all'accesso e subito dopo ogni cambio grafico. La tua modalità di contorno (outline) non viene toccata. Disattivare questa opzione ha effetto solo dopo un riavvio del gioco: /reload non basta.",
    ["Le jeu marque déjà la plupart des objets de quête avec son étincelle de butin. Ceci en ajoute une autre sur ceux que ton journal demande encore, d'après le nom de l'objectif (« Caisse de provisions »...). Coupé par défaut. Utilise le ciblage d'interaction du jeu : l'objet le plus proche, jusqu'à environ 15 m, tout autour de toi. Pour cela Platyplus allume « Activer la touche d'interaction » et les icônes d'interaction des objets du monde du jeu, et les remet comme avant quand tu coupes toutes les étincelles ci-dessous. Pas d'étincelle pendant un combat."] = "Il gioco segna già la maggior parte degli oggetti di missione con il suo bagliore del bottino. Questo ne aggiunge un altro su quelli che il tuo diario richiede ancora, in base al nome dell'obiettivo («Cassa di provviste»...). Disattivato di default. Usa il bersaglio di interazione del gioco: l'oggetto più vicino, fino a circa 15 m, tutto intorno a te. Per questo Platyplus attiva «Attiva il tasto di interazione» e le icone di interazione degli oggetti del mondo del gioco, e le rimette come prima quando disattivi tutti i bagliori qui sotto. Nessun bagliore durante il combattimento.",
    ["Le jeu protège une partie des caractéristiques en ce moment : affichage simplifié, sans détail au survol. Tout revient dès qu'il les rend lisibles."] = "Il gioco sta proteggendo una parte delle caratteristiche in questo momento: visualizzazione semplificata, senza dettagli al passaggio del mouse. Tutto torna non appena le rende di nuovo leggibili.",
    ["Le joueur dont la barre montre la mana. « Aucun » : ton groupe n'a pas de soigneur désigné et tu n'as pas choisi ton healer à la main."] = "Il giocatore di cui la barra mostra il mana. «Nessuno»: il tuo gruppo non ha un curatore designato e non hai scelto il tuo guaritore a mano.",
    ["Le journal aux couleurs de Platyplus : fond sombre arrondi, liserés fins, sélection en bleu, texte clair, et plus de parchemin sous les quêtes. Rien ne bouge : mêmes pages, mêmes boutons. Éteint : le look d'origine du journal (pierre, bronze et or). Prend effet après /reload."] = "Il diario con i colori di Platyplus: sfondo scuro arrotondato, bordi sottili, selezione in blu, testo chiaro e niente più pergamena sotto le missioni. Nulla si sposta: stesse pagine, stessi pulsanti. Disattivo: l'aspetto originale del diario (pietra, bronzo e oro). Ha effetto dopo /reload.",
    ["Le journal de quêtes de la carte du monde du jeu."] = "Il registro delle missioni della mappa del mondo del gioco.",
    ["Le journal des donjons : boss, butin, quêtes et plans de chaque donjon."] = "Il diario dei dungeon: boss, bottino, missioni e mappe di ogni dungeon.",
    ["Le journal des donjons est celui de l'addon DungeonJournal d'Exehn, installé à part : Platyplus l'ouvre d'ici, depuis le menu de l'icône et avec /pp donjons."] = "Il diario dei dungeon è quello dell'addon DungeonJournal di Exehn, installato separatamente: Platyplus lo apre da qui, dal menu dell'icona e con /pp donjons.",
    ["Le journal des donjons est celui de l'addon DungeonJournal d'Exehn, installé à part. Platyplus l'ouvre d'ici, depuis le menu de l'icône et avec /pp donjons, et pose dessus sa liste des donjons, « À ton niveau » et son style, sans rien changer dans l'addon."] = "Il diario dei dungeon è quello dell'addon DungeonJournal di Exehn, installato separatamente. Platyplus lo apre da qui, dal menu dell'icona e con /pp donjons, e vi applica sopra il suo elenco dei dungeon, «Al tuo livello» e il suo stile, senza cambiare nulla nell'addon.",
    ["Le journal des donjons n'est pas inclus dans cette version de Platyplus. Installe l'addon DungeonJournal d'Exehn depuis CurseForge : Platyplus l'ouvrira ensuite depuis cet onglet, depuis le menu de l'icône et avec /pp donjons, et posera dessus sa liste des donjons, « À ton niveau » et son style."] = "Il diario dei dungeon non è incluso in questa versione di Platyplus. Installa l'addon DungeonJournal di Exehn da CurseForge: Platyplus lo aprirà poi da questa scheda, dal menu dell'icona e con /pp donjons, e vi applicherà sopra il suo elenco dei dungeon, «Al tuo livello» e il suo stile.",
    ["Le journal des donjons n'est pas inclus dans cette version de Platyplus. Installe l'addon DungeonJournal d'Exehn depuis CurseForge : Platyplus l'ouvrira ensuite depuis cet onglet, depuis le menu de l'icône et avec /pp donjons."] = "Il diario dei dungeon non è incluso in questa versione di Platyplus. Installa l'addon DungeonJournal di Exehn da CurseForge: Platyplus lo aprirà poi da questa scheda, dal menu dell'icona e con /pp donjons.",
    ["Le marchand t'en donne"] = "Il mercante te ne dà",
    ["Le minuteur de ton attaque automatique : la barre se remplit jusqu'au prochain coup blanc. Pratique pour placer Frappe héroïque ou Heurtoir au bon moment."] = "Il timer del tuo attacco automatico: la barra si riempie fino al prossimo colpo bianco. Pratico per piazzare Colpo eroico o Schianto al momento giusto.",
    ["Le mode Recommandé, plus : les groupes de tes amis et de ta guilde acceptés, les invocations et les résurrections acceptées, les duels refusés, tout le courrier ouvert d'un coup, les quêtes acceptées et rendues sans appuyer sur la touche, la barre de mana du healer, la caméra plus loin, les têtes parlantes masquées, les objets de quête qui brillent."] = "La modalità Consigliato, in più: gruppi di amici e gilda accettati, evocazioni e resurrezioni accettate, duelli rifiutati, tutta la posta aperta in un colpo, missioni accettate e consegnate senza premere il tasto, la barra del mana del guaritore, la telecamera più lontana, le teste parlanti nascoste, gli oggetti delle missioni che brillano.",
    ["Le nom du sort, en petit sous la touche."] = "Il nome dell'incantesimo, in piccolo sotto il tasto.",
    ["Le petit logo en haut à droite de la fenêtre de chat."] = "Il piccolo logo in alto a destra della finestra della chat.",
    ["Le prix de tes objets à l'hôtel des ventes, partout : dans les infobulles et avant de fabriquer. Les prix viennent d'un scan complet de l'HDV et de ce que l'assistant trouve."] = "Il prezzo dei tuoi oggetti alla casa d'aste, ovunque: nelle descrizioni e prima di creare. I prezzi vengono da una scansione completa della casa d'aste e da ciò che trova l'assistente.",
    ["Le son d'avertissement de raid, au plus une fois par seconde."] = "Il suono di avviso dell'incursione, al massimo una volta al secondo.",
    ["Le sort part quand tu appuies, pas quand tu relâches. Disponible seulement si le client connaît ce réglage."] = "L'incantesimo parte quando premi, non quando rilasci. Disponibile solo se il client conosce questa impostazione.",
    ["Les 100 dernières lignes de chaque fenêtre, pour la session suivante."] = "Le ultime 100 righe di ogni finestra, per la sessione successiva.",
    ["Les adresses web écrites dans le chat (https://..., www....) deviennent des liens bleus. Un clic ouvre une petite fenêtre avec le lien déjà sélectionné : Ctrl+C pour le copier. Les messages protégés par le jeu (instances, combats de boss) ne sont jamais touchés."] = "Gli indirizzi web scritti nella chat (https://..., www....) diventano link blu. Un clic apre una piccola finestra con il link già selezionato: Ctrl+C per copiarlo. I messaggi protetti dal gioco (istanze, combattimenti contro boss) non vengono mai toccati.",
    ["Les armes et armures de qualité inférieure ne sont pas proposées. Par défaut Inhabituel (vert) : l'équipement blanc ou gris ne se vend pas à l'HDV, il part chez le marchand. Les marchandises (minerais, herbes, tissus...) sont toujours proposées."] = "Le armi e armature di qualità inferiore non vengono proposte. Di default Non comune (verde): l'equipaggiamento bianco o grigio non si vende alla casa d'aste, va dal mercante. Le merci (minerali, erbe, stoffe...) sono sempre proposte.",
    ["Les barres de vie au-dessus des mobs : couleurs de menace, quêtes, rares, et tout leur look."] = "Le barre della salute sopra i mob: colori della minaccia, missioni, rari e tutto il loro aspetto.",
    ["Les barres de vie des mobs changent de couleur selon qui ils attaquent. Ton rôle (tank ou dégâts) est deviné tout seul."] = "Le barre della salute dei mob cambiano colore in base a chi attaccano. Il tuo ruolo (tank o danni) viene riconosciuto da solo.",
    ["Les dés lancés à la main dans le chat, rangés par objet annoncé."] = "I dadi tirati a mano nella chat, ordinati per oggetto annunciato.",
    ["Les dés lancés à la main, rangés du plus haut au plus bas, avec l'objet lié juste avant dans le chat."] = "I dadi tirati a mano, ordinati dal più alto al più basso, con l'oggetto linkato subito prima nella chat.",
    ["Les fenêtres de chat du jeu (quand la fenêtre Platyplus est coupée) et la zone de saisie, aux couleurs de Platyplus."] = "Le finestre di chat del gioco (quando la finestra Platyplus è disattivata) e la casella di testo, con i colori di Platyplus.",
    ["Les fenêtres du jeu redessinées : plus grandes et plus lisibles."] = "Le finestre del gioco ridisegnate: più grandi e più leggibili.",
    ["Les fonctions utiles sont allumées : la touche d'interaction, le loot instantané, la vente et la réparation, les alertes de combat, les plates de menace, les fenêtres Platyplus, le chat amélioré. Ce qui décide à ta place reste coupé : invitations, invocations, duels, courrier."] = "Le funzioni utili sono attive: il tasto di interazione, il bottino istantaneo, la vendita e la riparazione, gli avvisi di combattimento, le targhette della minaccia, le finestre Platyplus, la chat migliorata. Ciò che decide al posto tuo resta spento: inviti, evocazioni, duelli, posta.",
    ["Les fonctions utiles sont déjà allumées : tu peux fermer cette fenêtre et jouer tout de suite."] = "Le funzioni utili sono già attive: puoi chiudere questa finestra e giocare subito.",
    ["Les fonctions utiles, sans rien décider à ta place. Le réglage de départ."] = "Le funzioni utili, senza decidere niente al posto tuo. L'impostazione di partenza.",
    ["Les messages arrivent comme d'habitude (tes réglages de canaux du jeu restent valables) et s'affichent dans la fenêtre Platyplus, une bulle par message, le nom dans la couleur de sa classe, le texte en clair. L'onglet Chat montre ce que les joueurs disent, l'onglet Jeu le reste (butin, expérience, système). Tire le bandeau pour la déplacer, le coin en bas à droite pour la redimensionner. Clic sur l'heure d'un message : le copier. La zone de saisie reste celle du jeu (Entrée pour écrire). Coupé : les fenêtres de chat du jeu reviennent."] = "I messaggi arrivano come al solito (le tue impostazioni dei canali del gioco restano valide) e appaiono nella finestra Platyplus, un fumetto per messaggio, il nome nel colore della sua classe, il testo semplice. La scheda Chat mostra ciò che dicono i giocatori, la scheda Gioco il resto (bottino, esperienza, sistema). Trascina la barra del titolo per spostarla, l'angolo in basso a destra per ridimensionarla. Clic sull'ora di un messaggio: copiarlo. La casella di testo resta quella del gioco (Invio per scrivere). Disattivo: tornano le finestre di chat del gioco.",
    ["Les miennes"] = "Le mie",
    ["Les miennes : hostile, neutre, amical et « tapé par d'autres » aux couleurs ci-dessous, avec ta texture. Celles du jeu : la barre normale du jeu. Les joueurs gardent toujours les couleurs du jeu."] = "Le mie: ostile, neutrale, amichevole e «colpito da altri» con i colori qui sotto, con la tua texture. Quelle del gioco: la barra normale del gioco. I giocatori mantengono sempre i colori del gioco.",
    ["Les mobs qui ne se battent pas avec toi."] = "I mob che non combattono con te.",
    ["Les objets au choix s'affichent au milieu de l'écran, colorés selon leur rareté."] = "Gli oggetti a scelta appaiono al centro dello schermo, colorati in base alla rarità.",
    ["Les objets exclus d'un clic droit dans le panneau de l'HDV seront de nouveau proposés."] = "Gli oggetti esclusi con un clic destro nel pannello della casa d'aste verranno di nuovo proposti.",
    ["Les objets gris et l'équipement moins bon que le tien se vendent tout seuls. Tu peux les racheter chez le marchand."] = "Gli oggetti grigi e l'equipaggiamento peggiore del tuo si vendono da soli. Puoi riacquistarli dal mercante.",
    ["Les objets tirés au sort par le jeu (Besoin, Cupidité, Passer), boss par boss."] = "Gli oggetti tirati a sorte dal gioco (Bisogno, Cupidigia, Passo), boss per boss.",
    ["Les pièces nettement moins bonnes que ce que tu portes."] = "I pezzi nettamente peggiori di ciò che indossi.",
    ["Les plantes et les cadavres qui ont encore du butin pour toi scintillent quand tu approches."] = "Le erbe e i cadaveri che hanno ancora bottino per te scintillano quando ti avvicini.",
    ["Les plus dangereux d'abord"] = "I più pericolosi per primi",
    ["Les sorts réactifs que Platyplus connaît pour ta classe. Pour en ajouter un autre, utilise la liste « Sorts ajoutés » juste en dessous."] = "Gli incantesimi reattivi che Platyplus conosce per la tua classe. Per aggiungerne un altro, usa l'elenco «Incantesimi aggiunti» subito sotto.",
    ["Les tranches de niveau sont colorées selon ton niveau :\n|cff66e680vert|r à ton niveau, |cffffd133or|r bientôt (1 à 3 niveaux), |cffff6666rouge|r trop dur pour l'instant, |cff99a1b3gris|r dépassé.\nÀ droite : tes quêtes faites dans le donjon (✓ : toutes)."] = "Le fasce di livello sono colorate in base al tuo livello:\n|cff66e680verde|r al tuo livello, |cffffd133oro|r presto (da 1 a 3 livelli), |cffff6666rosso|r troppo difficile per ora, |cff99a1b3grigio|r superato.\nA destra: le tue missioni completate nel dungeon (✓: tutte).",
    ["Les étincelles (onglet Butin) règlent cette portée : coupe-les pour la changer ici."] = "I bagliori (scheda Bottino) regolano questa portata: disattivali per cambiarla qui.",
    ["Lien [FR] pour traduire"] = "Link [FR] per tradurre",
    ["Lien web"] = "Link web",
    ["Liens web cliquables"] = "Link web cliccabili",
    ["Lignes au maximum"] = "Righe al massimo",
    ["Limite le nombre de pièces d'équipement vendues à chaque visite. Le rachat de Blizzard ne garde que les 12 derniers objets vendus : au-delà de 12, tu ne pourrais plus tout racheter en cas d'erreur."] = "Limita il numero di pezzi di equipaggiamento venduti a ogni visita. Il riacquisto di Blizzard conserva solo gli ultimi 12 oggetti venduti: oltre 12, non potresti più ricomprare tutto in caso di errore.",
    ["Lisibilité"] = "Leggibilità",
    ["Liste des donjons à gauche"] = "Elenco dei dungeon a sinistra",
    ["Liste les mobs en combat (plates, boss, cibles de ton groupe). Les couleurs sont celles des plates (onglet Plates). En donjon, le jeu cache certaines valeurs aux addons : la couleur reste juste, mais le tri par vie et certains chiffres peuvent manquer. Pas de clic pour cibler : le jeu l'interdit en combat."] = "Elenca i mob in combattimento (targhette, boss, bersagli del tuo gruppo). I colori sono quelli delle targhette (scheda Targhette). Nei dungeon, il gioco nasconde alcuni valori agli addon: il colore resta giusto, ma l'ordinamento per salute e alcuni numeri possono mancare. Nessun clic per selezionare: il gioco lo vieta in combattimento.",
    ["Liste les mobs en combat (plates, boss, cibles de ton groupe). Les couleurs sont celles des plates (onglet Plates). En donjon, le jeu cache certaines valeurs aux addons : la couleur reste juste, mais le tri par vie et certains chiffres peuvent manquer. Survole une ligne : infobulle (état en clair, vie, menace) et la plate du mob est mise en évidence dans le monde ; clic droit : pose ou retire le marqueur Crâne. Pas de clic pour cibler : le jeu l'interdit en combat."] = "Elenca i nemici in combattimento (targhette, boss, bersagli del tuo gruppo). I colori sono quelli delle targhette (scheda Targhette). Nei dungeon il gioco nasconde alcuni valori agli addon: il colore resta giusto, ma l'ordine per salute e alcuni numeri possono mancare. Passa sopra una riga: descrizione (stato in chiaro, salute, minaccia) e la targhetta del nemico viene evidenziata nel mondo; clic destro: mette o toglie il segnalino Teschio. Nessun clic per bersagliare: il gioco lo vieta in combattimento.",
    ["Liste les mobs en combat (plates, boss, cibles de ton groupe). Les couleurs sont celles des plates (onglet Plates). En donjon, le jeu cache certaines valeurs aux addons : la couleur reste juste, mais le tri par vie et certains chiffres peuvent manquer. Survole une ligne : infobulle (état en clair, vie, menace) et la plate du mob est mise en évidence dans le monde. Pas de clic pour cibler : le jeu l'interdit en combat."] = "Elenca i nemici in combattimento (targhette, boss, bersagli del tuo gruppo). I colori sono quelli delle targhette (scheda Targhette). Nei dungeon il gioco nasconde alcuni valori agli addon: il colore resta giusto, ma l'ordine per salute e alcuni numeri possono mancare. Passa sopra una riga: descrizione (stato in chiaro, salute, minaccia) e la targhetta del nemico viene evidenziata nel mondo. Nessun clic per bersagliare: il gioco lo vieta in combattimento.",
    ["Liste les mobs en combat (plates, boss, cibles de ton groupe). Les couleurs sont celles des plates (onglet Plates). En donjon, le jeu cache certaines valeurs aux addons : la couleur reste juste, mais le tri par vie et certains chiffres peuvent manquer. Survole une ligne : infobulle (état en clair, vie, menace) et la plate du mob est mise en évidence dans le monde. Pas de clic pour cibler ni marquer : le jeu l'interdit aux addons."] = "Elenca i nemici in combattimento (targhette, boss, bersagli del tuo gruppo). I colori sono quelli delle targhette (scheda Targhette). Nei dungeon il gioco nasconde alcuni valori agli addon: il colore resta giusto, ma l'ordine per salute e alcuni numeri possono mancare. Passa sopra una riga: descrizione (stato in chiaro, salute, minaccia) e la targhetta del nemico viene evidenziata nel mondo. Nessun clic per bersagliare o marcare: il gioco lo vieta agli addon.",
    ["Liste les objets de tes sacs que l'HDV accepte, avec un prix pour chacun. Ne sont jamais proposés : objets liés, équipement blanc ou gris, outils de métier (pioche, couteau à dépecer, canne à pêche...), objets d'un ensemble d'équipement. Clic sur une ligne : cocher / décocher. Seuls les objets cochés sont mis en vente. Clic droit : ne plus jamais proposer cet objet."] = "Elenca gli oggetti delle tue borse che la casa d'aste accetta, con un prezzo per ciascuno. Non vengono mai proposti: oggetti vincolati, equipaggiamento bianco o grigio, strumenti di professione (piccone, coltello da scuoiatore, canna da pesca...), oggetti di un set di equipaggiamento. Clic su una riga: seleziona / deseleziona. Solo gli oggetti selezionati vengono messi in vendita. Clic destro: non proporre mai più questo oggetto.",
    ["Lit l'historique de butin du jeu : rien n'est envoyé aux autres joueurs."] = "Legge la cronologia del bottino del gioco: non viene inviato nulla agli altri giocatori.",
