    ["Reste"] = "Resta",
    ["Revoir la visite guidée"] = "Rivedi la visita guidata",
    ["Rien ne t'attaque."] = "Niente ti sta attaccando.",
    ["Rien ne t'échappe : ce que tu peux ramasser brille quand tu t'en approches."] = "Niente ti sfugge: ciò che puoi raccogliere brilla quando ti avvicini.",
    ["Rien à mettre en vente"] = "Niente da mettere in vendita",
    ["Rien à proposer : aucun objet de tes sacs ne peut aller à l'HDV (objets liés, équipement blanc ou gris, outils de métier, ou objets exclus)."] = "Niente da proporre: nessun oggetto delle tue borse può andare alla Casa d'aste (oggetti vincolati, equipaggiamento bianco o grigio, strumenti di professione, oppure oggetti esclusi).",
    ["Rien à vendre (pas d'objet fabriqué)"] = "Niente da vendere (nessun oggetto fabbricato)",
    ["Rien à vendre."] = "Niente da vendere.",
    ["Rond"] = "Rotondo",
    ["Rugissement"] = "Ruggito",
    ["Runes"] = "Rune",
    ["RÉCOMPENSES"] = "RICOMPENSE",
    ["Récompense"] = "Ricompensa",
    ["Récompenses en grandes cartes"] = "Ricompense in grandi carte",
    ["Récupère objets et argent dès que tu ouvres la boîte aux lettres."] = "Recupera oggetti e denaro appena apri la cassetta della posta.",
    ["Réduit au silence"] = "Ridotto al silenzio",
    ["Réglage du jeu (Options > Plates d'unités). Grande = 25 % de plus que la taille normale, Énorme = 60 %. Se change hors combat."] = "Impostazione del gioco (Opzioni > Targhette delle unità). Grande = 25 % più della dimensione normale, Enorme = 60 %. Si cambia fuori combattimento.",
    ["Réglage du jeu (et non de Platyplus) : il est conservé par le jeu."] = "Impostazione del gioco (e non di Platyplus): viene conservata dal gioco.",
    ["Réglage du jeu. Fine : 13 px de haut ; Épaisse : 20 px, bien plus lisible en combat ; Bloc : épaisse, et la barre d'incantation aussi. Se change hors combat."] = "Impostazione del gioco. Sottile: 13 px di altezza; Spessa: 20 px, molto più leggibile in combattimento; Blocco: spessa, e anche la barra di lancio. Si cambia fuori combattimento.",
    ["Réglages du jeu"] = "Impostazioni del gioco",
    ["Réglages du jeu recommandés, en un clic."] = "Impostazioni del gioco consigliate, con un clic.",
    ["Réglages personnalisés, à partir du mode %s. Choisir un mode remet tous ses interrupteurs."] = "Impostazioni personalizzate, a partire dalla modalità %s. Scegliere una modalità ripristina tutti i suoi interruttori.",
    ["Réglages rapides"] = "Impostazioni rapide",
    ["Réglages recommandés"] = "Impostazioni consigliate",
    ["Régler le recul maximum de la caméra"] = "Regola la distanza massima della telecamera",
    ["Réinitialisation"] = "Ripristino",
    ["Réparation"] = "Riparazione",
    ["Répare chez un marchand (Platyplus peut réparer tout seul : voir les options)."] = "Ripara presso un mercante (Platyplus può riparare da solo: vedi le opzioni).",
    ["Répare tout ton équipement à l'ouverture d'un marchand qui sait réparer. Le coût s'affiche dans le flux."] = "Ripara tutto il tuo equipaggiamento all'apertura di un mercante che sa riparare. Il costo appare nel flusso.",
    ["Réparer automatiquement"] = "Ripara automaticamente",
    ["Réparer chez les marchands"] = "Ripara dai mercanti",
    ["Réparé"] = "Riparato",
    ["Réputation"] = "Reputazione",
    ["Réputations indisponibles sur ce client."] = "Reputazioni non disponibili su questo client.",
    ["Résistance : %s"] = "Resistenza: %s",
    ["Résistances"] = "Resistenze",
    ["Rétablir mes anciens réglages"] = "Ripristina le mie vecchie impostazioni",
    ["Rétablit la touche par défaut de Platyplus ((aucune))."] = "Ripristina il tasto predefinito di Platyplus ((nessuno)).",
    ["Rétablit la touche par défaut de Platyplus (F)."] = "Ripristina il tasto predefinito di Platyplus (F).",
    ["S'il te manque en combat : son icône et sa touche, comme une alerte de proc."] = "Se ti manca in combattimento: la sua icona e il suo tasto, come un avviso di proc.",
    ["S'ouvre avec la touche des sacs, chez le marchand, à la banque ou au courrier."] = "Si apre con il tasto delle borse, dal mercante, in banca o alla posta.",
    ["Sacs"] = "Borse",
    ["Saison %d"] = "Stagione %d",
    ["Sans Alt, et gardé d'une session à l'autre."] = "Senza Alt, e conservato da una sessione all'altra.",
    ["Sans appuyer sur rien. Maintiens Maj en parlant au PNJ pour faire une pause."] = "Senza premere nulla. Tieni premuto Maiusc mentre parli con il PNG per fare una pausa.",
    ["Sans rang"] = "Senza grado",
    ["Scan complet automatique"] = "Scansione completa automatica",
    ["Se remplit à la vitesse de ton arme et repart à chaque coup blanc (le jeu le signale lui-même). Le temps restant s'affiche à droite. Elle devient dorée quand Frappe héroïque ou Enchaînement attend le prochain coup, et pâlit quand ta cible est hors de portée."] = "Si riempie alla velocità della tua arma e riparte a ogni colpo bianco (lo segnala il gioco stesso). Il tempo rimanente appare a destra. Diventa dorata quando Colpo eroico o Fendente attende il prossimo colpo, e sbiadisce quando il tuo bersaglio è fuori portata.",
    ["Se vend le plus cher"] = "Si vende al prezzo più alto",
    ["Sens d'empilement"] = "Direzione di impilamento",
    ["Ses réglages"] = "Le sue impostazioni",
    ["Session"] = "Sessione",
    ["Seuil d'alerte"] = "Soglia di avviso",
    ["Seul, tu sais déjà que les mobs te tapent : la fenêtre ne s'affiche pas."] = "Da solo sai già che i mob ti colpiscono: la finestra non appare.",
    ["Seulement en combat"] = "Solo in combattimento",
    ["Seulement en combat."] = "Solo in combattimento.",
    ["Seulement en groupe"] = "Solo in gruppo",
    ["Si l'addon Threat Plates est actif, il remplace les plates du jeu : désactive-le pour voir celles-ci. Les cadavres à fouiller ont déjà leurs étincelles (onglet Butin). /pp plates : ce que voit chaque plate."] = "Se l'addon Threat Plates è attivo, sostituisce le targhette del gioco: disattivalo per vedere queste. I cadaveri da saccheggiare hanno già i loro bagliori (scheda Bottino). /pp plates: ciò che vede ogni targhetta.",
    ["Si le marchand t'en donne autant ou plus, l'objet n'est pas mis en vente."] = "Se il mercante te ne dà altrettanto o di più, l'oggetto non viene messo in vendita.",
    ["Si ta guilde l'autorise, la réparation est payée par la banque de guilde ; sinon, avec ton argent."] = "Se la tua gilda lo permette, la riparazione è pagata dalla banca della gilda; altrimenti, con il tuo denaro.",
    ["Si tu fais des dégâts : vert quand le mob t'ignore, orange quand ça se joue, rouge quand il t'attaque. Si tu tankes, c'est l'inverse : rouge, il t'échappe."] = "Se fai danni: verde quando il mob ti ignora, arancione quando si gioca sul filo, rosso quando ti attacca. Se fai il tank è l'inverso: rosso, ti sfugge.",
    ["Soins (pas interruptible)"] = "Cure (non interrompibile)",
    ["Son quand ta cible incante"] = "Suono quando il tuo bersaglio lancia un incantesimo",
    ["Son à l'apparition"] = "Suono alla comparsa",
    ["Sorts ajoutés"] = "Incantesimi aggiunti",
    ["Sorts ignorés"] = "Incantesimi ignorati",
    ["Sorts qui brillent"] = "Incantesimi che brillano",
    ["Sorts réactifs de ma classe"] = "Incantesimi reattivi della mia classe",
    ["Sorts surveillés"] = "Incantesimi monitorati",
    ["Souris %s"] = "Topo %s",
    ["Sous le seuil, la barre devient rouge et clignote."] = "Sotto la soglia, la barra diventa rossa e lampeggia.",
    ["Spé 2"] = "Spec 2",
    ["Style Platyplus"] = "Stile Platyplus",
    ["Styles prêts à l'emploi :"] = "Stili pronti all'uso:",
    ["Suivant"] = "Avanti",
    ["Suivre aussi les /roll"] = "Segui anche i /roll",
    ["Suivre les jets de butin"] = "Segui i tiri per il bottino",
    ["Suivre sur la barre"] = "Segui sulla barra",
    ["Sur ce personnage"] = "Su questo personaggio",
    ["Sur la fiche du personnage"] = "Sulla scheda del personaggio",
    ["Sur la plate : ta progression de quête (« 3/8 ») et l'étiquette « Rare »."] = "Sulla targhetta: il tuo avanzamento della missione (« 3/8 ») e l'etichetta « Raro ».",
    ["Sur les grandes cartes de l'accueil, la tranche de niveau prend la même couleur et une pastille « À ton niveau » ou « Bientôt » s'ajoute. La première fois que tu ouvres l'accueil, il défile jusqu'aux donjons de ton niveau."] = "Sulle grandi carte della home, la fascia di livello prende lo stesso colore e si aggiunge un'etichetta «Al tuo livello» o «Presto». La prima volta che apri la home, scorre fino ai dungeon del tuo livello.",
    ["Sur les objets des sacs"] = "Sugli oggetti delle borse",
    ["Système"] = "Sistema",
    ["Sûr ? (re-clique)"] = "Sicuro? (clicca di nuovo)",
    ["Ta cible"] = "Il tuo bersaglio",
    ["Ta cible esquive : l'icône de Fulgurance apparaît avec « 3 » dessous si elle est sur la touche 3."] = "Il tuo bersaglio schiva: l'icona di Sopraffazione appare con «3» sotto se è sul tasto 3.",
    ["Ta position sur la carte de la zone."] = "La tua posizione sulla mappa della zona.",
    ["Ta touche"] = "Il tuo tasto",
    ["Tabard"] = "Tabarro",
    ["Taille"] = "Dimensione",
    ["Taille de l'icône"] = "Dimensione dell'icona",
    ["Taille de la fenêtre"] = "Dimensione della finestra",
    ["Taille des messages dans la fenêtre de chat Platyplus."] = "Dimensione dei messaggi nella finestra della chat Platyplus.",
    ["Taille des plates"] = "Dimensione delle targhette",
    ["Taille du texte"] = "Dimensione del testo",
    ["Taille, nombre, animation et son des alertes."] = "Dimensione, numero, animazione e suono degli avvisi.",
    ["Taille, épaisseur, texture, transparence."] = "Dimensione, spessore, texture, trasparenza.",
    ["Tank : en haut, les mobs que tu n'as pas ou que tu perds. DPS : en haut, ceux qui te tapent. Par vie : impossible quand le jeu cache la vie des mobs (ordre d'arrivée dans ce cas)."] = "Tank: in alto, i mob che non hai o che stai perdendo. DPS: in alto, quelli che ti colpiscono. Per salute: impossibile quando il gioco nasconde la salute dei mob (in quel caso, ordine di arrivo).",
    ["Tank : il tape un allié. DPS/soins : il te tape."] = "Tank: colpisce un alleato. DPS/cure: colpisce te.",
    ["Tank : le mob te tape. DPS/soins : il ne te regarde pas."] = "Tank: il mob colpisce te. DPS/cure: non ti guarda.",
    ["Tank : quand un mob qui te tapait part sur un allié, sa plate clignote pour que tu le reprennes (Provocation, Coup railleur...)."] = "Tank: quando un mob che ti colpiva passa a un alleato, la sua targhetta lampeggia perché tu lo riprenda (Provocazione, Colpo beffardo...).",
    ["Tank : seulement les mobs que je n'ai pas"] = "Tank: solo i mob che non ho",
    ["Tank : un éclat rouge sur la ligne d'un mob qui te tapait et tape maintenant quelqu'un d'autre. Sans son."] = "Tank: un lampo rosso sulla riga di un mob che ti colpiva e ora colpisce qualcun altro. Senza suono.",
    ["Tape /pp ou clique sur l'icône Platyplus : chaque fonction a son interrupteur, et chaque réglage s'explique quand tu le survoles. Pour revoir cette visite : /pp bienvenue."] = "Digita /pp o clicca sull'icona Platyplus: ogni funzione ha il suo interruttore e ogni impostazione si spiega quando ci passi sopra con il mouse. Per rivedere questa visita: /pp welcome.",
    ["Tapé par d'autres"] = "Colpito da altri",
    ["Temps de jeu actif"] = "Tempo di gioco attivo",
    ["Temps de réponse du serveur, en millisecondes."] = "Tempo di risposta del server, in millisecondi.",
    ["Temps pendant lequel une ligne reste affichée avant de s'estomper."] = "Tempo per cui una riga resta visibile prima di svanire.",
    ["Temps restant"] = "Tempo rimanente",
    ["Temps écoulé · gagnant inconnu"] = "Tempo scaduto · vincitore sconosciuto",
    ["Tenu par un autre tank"] = "Tenuto da un altro tank",
    ["Terminer"] = "Fine",
    ["Tes mots à masquer"] = "Le parole da nascondere",
    ["Tes sacs à la suite dans une grille. Les cases sont celles du jeu : clic droit pour utiliser ou vendre, glisser pour déplacer, Maj-clic pour lier ou partager une pile. Exemple : tape « lin » dans Chercher, seules tes Étoffes de lin restent allumées. Tire le bandeau pour déplacer la fenêtre. Coupé : les sacs du jeu reviennent."] = "Le tue borse una dopo l'altra in una griglia. Gli slot sono quelli del gioco: clic destro per usare o vendere, trascina per spostare, Maiusc+clic per linkare o dividere una pila. Esempio: digita «lino» in Cerca, restano accese solo le tue Stoffe di lino. Trascina la barra del titolo per spostare la finestra. Disattivo: tornano le borse del gioco.",
    ["Tester"] = "Prova",
    ["Texte dans la couleur du canal"] = "Testo nel colore del canale",
    ["Texte de statut du jeu : écrit les valeurs exactes sur les barres de vie et de ressource."] = "Testo di stato del gioco: scrive i valori esatti sulle barre della salute e della risorsa.",
    ["Texture"] = "Texture",
    ["Threat Plates"] = "Threat Plates",
    ["Tire son bandeau pour la déplacer : elle s'ouvrira ensuite toujours à cet endroit."] = "Trascina la sua barra del titolo per spostarla: si aprirà poi sempre in quel punto.",
    ["Titre : %s"] = "Titolo: %s",
    ["Ton mode"] = "La tua modalità",
    ["Ton niveau"] = "Il tuo livello",
    ["Ton nom apparaît en jaune dans le message, un petit son est joué (au plus toutes les 3 secondes) et l'icône du jeu clignote dans la barre des tâches si tu es sur une autre fenêtre. Les chuchotements ont déjà leur son dans le jeu."] = "Il tuo nome appare in giallo nel messaggio, viene emesso un piccolo suono (al massimo ogni 3 secondi) e l'icona del gioco lampeggia nella barra delle applicazioni se sei su un'altra finestra. I sussurri hanno già il loro suono nel gioco.",
    ["Ton nom surligné, avec un son"] = "Il tuo nome evidenziato, con un suono",
    ["Ton prix"] = "Il tuo prezzo",
    ["Ton prix = le moins cher des autres vendeurs, moins ce montant en pièces de cuivre (au moins 1 pc de moins, pour passer devant). Si le moins cher est déjà à toi, tu t'alignes dessus au lieu de te concurrencer."] = "Il tuo prezzo = il più basso degli altri venditori, meno questa quantità in monete di rame (almeno 1 pc in meno, per passare davanti). Se il più basso è già tuo, ti allinei invece di farti concorrenza.",
    ["Ton raccourci vers tout Platyplus, posé où tu veux à l'écran."] = "La tua scorciatoia verso tutto Platyplus, posizionata dove vuoi sullo schermo.",
    ["Ton équipement est réparé dès que tu parles à un marchand qui sait réparer."] = "Il tuo equipaggiamento viene riparato appena parli con un mercante che sa riparare.",
    ["Ton équipement est réparé, avec l'argent de la guilde quand c'est possible."] = "Il tuo equipaggiamento viene riparato, con il denaro della gilda quando possibile.",
    ["Total des composants"] = "Totale dei componenti",
    ["Total estimé : %s"] = "Totale stimato: %s",
    ["Total pour %d"] = "Totale per %d",
    ["Touche : %s"] = "Tasto: %s",
    ["Touche d'interaction"] = "Tasto di interazione",
    ["Touche de mise en vente"] = "Tasto di messa in vendita",
    ["Touche pour boire"] = "Tasto per bere",
    ["Touche pour manger"] = "Tasto per mangiare",
    ["Toujours vendre"] = "Vendi sempre",
    ["Toujours vendre : %d"] = "Vendi sempre: %d",
    ["Tous les mobs en combat avec ton groupe, et qui les tient."] = "Tutti i mob in combattimento con il tuo gruppo, e chi li tiene.",
    ["Tous les réglages dans l'onglet"] = "Tutte le impostazioni nella scheda",
    ["Tous les réglages dans les onglets"] = "Tutte le impostazioni nelle schede",
    ["Tous tes mobs sont tenus."] = "Tutti i tuoi mob sono sotto controllo.",
    ["Tous tes sacs dans une seule fenêtre Platyplus, avec recherche, tri, argent et places libres."] = "Tutte le tue borse in un'unica finestra Platyplus, con ricerca, ordinamento, denaro e slot liberi.",
    ["Tous tes sacs dans une seule fenêtre."] = "Tutte le tue borse in un'unica finestra.",
    ["Tout allumé, avec les automatismes : invitations, invocations, courrier…"] = "Tutto attivo, automatismi compresi: inviti, evocazioni, posta…",
    ["Tout appliquer"] = "Applica tutto",
    ["Tout cocher"] = "Seleziona tutto",
    ["Tout coupé sauf l'icône : tu allumes seulement ce que tu veux."] = "Tutto spento tranne l'icona: attivi solo quello che vuoi.",
    ["Tout décocher"] = "Deseleziona tutto",
    ["Tout est prêt !"] = "Tutto pronto!",
    ["Tout est ramassé d'un coup, et tu vois ce que tu gagnes sans ouvrir tes sacs."] = "Tutto viene raccolto in un colpo solo e vedi cosa ottieni senza aprire le borse.",
    ["Tout est ramassé dès l'ouverture, sans fenêtre de butin."] = "Tutto viene raccolto all'apertura, senza finestra del bottino.",
    ["Tout le contenu d'un cadavre ou d'un coffre est ramassé dès l'ouverture."] = "Tutto il contenuto di un cadavere o di un forziere viene raccolto appena lo apri.",
    ["Tout le monde a passé"] = "Tutti hanno passato",
    ["Tout remettre par défaut"] = "Rimetti tutto di default",
    ["Tout réinitialiser"] = "Azzera tutto",
    ["Tout réinitialiser (garder mes listes)"] = "Azzera tutto (mantieni le mie liste)",
    ["Tout se règle avec /pp"] = "Tutto si regola con /pp",
    ["Tout sort que le jeu entoure d'une lueur sur tes barres : c'est le cas des procs des autres classes."] = "Ogni incantesimo che il gioco circonda di un alone sulle tue barre: è il caso dei proc delle altre classi.",
    ["Tout va bien"] = "Tutto bene",
    ["Toutes les fonctions sont coupées, sauf l'icône Platyplus qui ouvre les options. Le jeu redevient presque comme sans l'addon ; allume ensuite ce que tu veux, onglet par onglet."] = "Tutte le funzioni sono spente, tranne l'icona Platyplus che apre le opzioni. Il gioco torna quasi come senza l'addon; poi attiva quello che vuoi, scheda per scheda.",
    ["Toutes tes quêtes sont faites (%d)"] = "Tutte le tue missioni sono completate (%d)",
    ["Traducteur"] = "Traduttore",
    ["Traduit le chat des joueurs étrangers avec une petite IA qui tourne sur ton PC (programme « Traducteur Platyplus », à lancer à côté du jeu)."] = "Traduce la chat dei giocatori stranieri con una piccola IA che gira sul tuo PC (programma «Traduttore Platyplus», da avviare accanto al gioco).",
    ["Trier les sacs"] = "Ordina le borse",
    ["Très rond"] = "Molto rotondo",
    ["Tu es en train de le perdre"] = "Lo stai perdendo",
    ["Tu le tiens"] = "Lo hai tu",
    ["Tu n'as choisi personne à la main."] = "Non hai scelto nessuno a mano.",
    ["Tu pourras choisir un de ces objets :"] = "Potrai scegliere uno di questi oggetti:",
    ["Tu recevras :"] = "Riceverai:",
    ["Tu recevras aussi :"] = "Riceverai anche:",
    ["Tu vas prendre l'aggro"] = "Stai per prendere l'aggro",
    ["Témoin : clique ici pour te cibler toi-même"] = "Controllo: clicca qui per selezionare te stesso",
    ["Un ! jaune pour un mob à tuer, un sac pour un mob qui laisse un objet de quête, avec ta progression. Disparaît quand l'objectif est fini. Les objectifs de tes équipiers sont ignorés."] = "Un ! giallo per un mob da uccidere, una borsa per un mob che lascia un oggetto di missione, con i tuoi progressi. Scompare quando l'obiettivo è completato. Gli obiettivi dei tuoi compagni vengono ignorati.",
    ["Un 2e /roll du même joueur pour le même objet est signalé et ne compte pas. Une égalité au plus haut dé est signalée."] = "Un secondo /roll dello stesso giocatore per lo stesso oggetto viene segnalato e non conta. Un pareggio sul tiro più alto viene segnalato.",
    ["Un add-on n'a ni Internet ni IA : la traduction est faite par le programme Traducteur Platyplus (dossier Platyplus\\Traducteur), qui s'affiche par-dessus le jeu. Clic sur [FR] : une fine bande de couleurs apparaît une demi-seconde en haut à gauche de l'écran, le programme la lit et traduit. Clic droit sur [FR] : le message dans une zone à copier (Ctrl+C), si la bande ne passe pas. Dans le jeu, Ctrl+Entrée ouvre une zone où tu écris en français : la traduction est copiée, colle-la dans le chat avec Ctrl+V. Pas de lien sur les messages protégés par le jeu (en instance)."] = "Un addon non ha né Internet né IA: la traduzione è fatta dal programma Traduttore Platyplus (cartella Platyplus\\Traducteur), che appare sopra il gioco. Clic su [FR]: una sottile striscia di colori appare per mezzo secondo in alto a sinistra dello schermo, il programma la legge e traduce. Clic destro su [FR]: il messaggio in una casella da copiare (Ctrl+C), se la striscia non passa. Nel gioco, Ctrl+Invio apre una casella dove scrivi in francese: la traduzione viene copiata, incollala nella chat con Ctrl+V. Nessun link sui messaggi protetti dal gioco (in istanza).",
    ["Un autre joueur l'a touché en premier : pas d'XP ni de butin pour toi."] = "Un altro giocatore l'ha colpito per primo: niente XP né bottino per te.",
    ["Un bandeau au milieu de l'écran te signale que la touche utilisera l'objet de quête. Éteint, la touche marche pareil, sans rien afficher."] = "Un banner al centro dello schermo ti segnala che il tasto userà l'oggetto di missione. Disattivo, il tasto funziona allo stesso modo, senza mostrare nulla.",
    ["Un cadavre qui a encore du butin pour toi brille à l'approche."] = "Un cadavere che ha ancora del bottino per te brilla quando ti avvicini.",
    ["Un chat plus beau, plus lisible, qui se souvient, sans spam."] = "Una chat più bella, più leggibile, che ricorda, senza spam.",
    ["Un chat plus lisible : onglets, anti-spam, et l'historique gardé après un /reload."] = "Una chat più leggibile: schede, anti-spam e cronologia conservata dopo un /reload.",
    ["Un clic ouvre le lien, prêt à copier (Ctrl+C)."] = "Un clic apre il link, pronto da copiare (Ctrl+C).",
    ["Un clic règle toutes les fonctions d'un coup. Tu ajustes ensuite ce que tu veux, ici ou avec /pp."] = "Un clic regola tutte le funzioni in una volta. Poi sistemi quello che vuoi, qui o con /pp.",
    ["Un mob qui t'attaquera si tu t'approches."] = "Un mob che ti attaccherà se ti avvicini.",
    ["Un mode allume ou coupe toutes les fonctions d'un coup : une base, que tu ajustes ensuite dans les autres onglets. Survole un mode pour voir exactement ce qu'il change."] = "Una modalità attiva o disattiva tutte le funzioni in una volta: una base che poi sistemi nelle altre schede. Passa sopra una modalità per vedere esattamente cosa cambia.",
    ["Un mode ne change pas ta touche d'interaction, tes listes (« Ne jamais vendre », sorts ajoutés…), les positions, les tailles, les couleurs ni les réglages du jeu."] = "Una modalità non cambia il tuo tasto di interazione, le tue liste («Non vendere mai», incantesimi aggiunti…), le posizioni, le dimensioni, i colori né le impostazioni del gioco.",
    ["Un mode pour commencer"] = "Una modalità per iniziare",
    ["Un panneau à droite de la fenêtre de l'HDV."] = "Un pannello a destra della finestra della casa d'aste.",
    ["Un petit « tic » quand une alerte apparaît."] = "Un piccolo «tic» quando appare un avviso.",
    ["Un réglage que ton client ne connaît pas est grisé."] = "Un'impostazione che il tuo client non conosce è disattivata (grigia).",
    ["Un son discret à chaque nouvelle alerte, au plus un par seconde. Exemple : Fulgurance devient prête, tu l'entends sans regarder. Le bouton Aperçu le joue aussi."] = "Un suono discreto a ogni nuovo avviso, al massimo uno al secondo. Esempio: Sopraffazione diventa pronta, lo senti senza guardare. Anche il pulsante Anteprima lo riproduce.",
    ["Un son quand ta cible commence un sort que tu peux interrompre (au plus une fois par seconde)."] = "Un suono quando il tuo bersaglio inizia un incantesimo che puoi interrompere (al massimo una volta al secondo).",
    ["Un sort ajouté ici est annoncé dès qu'il est sur une de tes barres, utilisable et hors recharge, comme un sort réactif. Exemple : ajoute Coup de bouclier pour voir son icône et sa touche chaque fois qu'il est prêt. Glisse le sort depuis ton grimoire, ou tape son nom. En combat, si le jeu cache la recharge, un sort ajouté peut rester affiché pendant sa recharge."] = "Un incantesimo aggiunto qui viene segnalato appena è su una delle tue barre, utilizzabile e fuori recupero, come un incantesimo reattivo. Esempio: aggiungi Colpo di scudo per vedere la sua icona e il suo tasto ogni volta che è pronto. Trascina l'incantesimo dal tuo libro degli incantesimi, o digita il suo nome. In combattimento, se il gioco nasconde il recupero, un incantesimo aggiunto può restare visibile durante il suo recupero.",
    ["Un sort ignoré n'a jamais d'alerte, même s'il brille. Exemple : un sort qui brille tout le temps et t'encombre l'écran : ajoute-le ici. Tous les rangs du sort sont ignorés (reconnus par leur nom)."] = "Un incantesimo ignorato non ha mai un avviso, anche se brilla. Esempio: un incantesimo che brilla sempre e ti ingombra lo schermo: aggiungilo qui. Tutti i gradi dell'incantesimo vengono ignorati (riconosciuti dal nome).",
    ["Un souci ? Tape /pp etincelles : il montre ce que Platyplus voit autour de toi."] = "Un problema? Digita /pp etincelles: mostra ciò che Platyplus vede intorno a te.",
    ["Un souci, une idée ? Écris-nous sur github.com/bloufed/Platyplus."] = "Un problema, un'idea? Scrivici su github.com/bloufed/Platyplus.",
    ["Une barre de mana pour le soigneur de ton groupe, posée où tu veux à l'écran : son nom et « 4 320 / 6 800 »."] = "Una barra del mana per il curatore del tuo gruppo, posizionata dove vuoi sullo schermo: il suo nome e «4.320 / 6.800».",
    ["Une barre qui se remplit jusqu'à ton prochain coup automatique. Visible en combat seulement."] = "Una barra che si riempie fino al tuo prossimo colpo automatico. Visibile solo in combattimento.",
    ["Une base de réglages en un clic : Recommandé, Complet, Immersif ou Minimal."] = "Una base di impostazioni in un clic: Consigliato, Completo, Immersivo o Minimo.",
    ["Une colonne collée au journal, avec tous les donjons dans l'ordre des niveaux : un clic ouvre un donjon, depuis n'importe quelle page. La tranche de niveau est en couleur selon ton niveau (vert : à ton niveau, or : bientôt, rouge : trop dur, gris : dépassé), et à droite tes quêtes faites (par exemple 2/7, ✓ quand tout est fait). « Accueil » ramène aux grandes cartes."] = "Una colonna attaccata al diario, con tutti i dungeon in ordine di livello: un clic apre un dungeon, da qualsiasi pagina. La fascia di livello è colorata in base al tuo livello (verde: al tuo livello, oro: presto, rosso: troppo difficile, grigio: superato), e a destra le tue missioni completate (per esempio 2/7, ✓ quando tutte). «Home» riporta alle grandi carte.",
    ["Une couleur à part quand un autre tank du groupe tient le mob."] = "Un colore a parte quando un altro tank del gruppo tiene il mob.",
    ["Une fine barre en dessous si tu as deux armes."] = "Una barra sottile sotto se hai due armi.",
    ["Une icône posée où tu veux à l'écran (hors minicarte). Clic gauche : cette fenêtre. Clic droit : un menu pour allumer ou couper les fonctions. Glisse-la pour la déplacer."] = "Un'icona posizionata dove vuoi sullo schermo (fuori dalla minimappa). Clic sinistro: questa finestra. Clic destro: un menu per attivare o disattivare le funzioni. Trascinala per spostarla.",
    ["Une ligne par mob : nom, vie, qui le tient, ta menace. Vert : tu l'as, orange : tu le perds, rouge : tu ne l'as plus, bleu : un autre tank le tient, gris : il n'a pas de cible. DPS : rouge = il te tape (compteur « N sur toi »)."] = "Una riga per mob: nome, salute, chi lo tiene, la tua minaccia. Verde: ce l'hai, arancione: lo stai perdendo, rosso: non ce l'hai più, blu: un altro tank lo tiene, grigio: non ha bersaglio. DPS: rosso = colpisce te (contatore «N su di te»).",
    ["Une ligne « HDV » sur les objets : sacs, équipement porté, liens..."] = "Una riga «Casa d'aste» sugli oggetti: borse, equipaggiamento indossato, link...",
    ["Une liste « Ne jamais vendre » protège ce que tu veux garder, et un aperçu montre ce qui partira."] = "Un elenco « Non vendere mai » protegge ciò che vuoi tenere e un'anteprima mostra cosa verrà venduto.",
    ["Une mise en vente par clic"] = "Una messa in vendita per clic",
    ["Une petite icône à droite des alertes tant que tu as le buff Maîtrise du blocage."] = "Una piccola icona a destra degli avvisi finché hai il potenziamento Blocco con scudo.",
    ["Une pierre de soins"] = "Una pietra della salute",
    ["Une pièce n'est vendue que si son niveau d'objet est inférieur d'au moins ce nombre de points à celui de la pièce équivalente que tu portes."] = "Un pezzo viene venduto solo se il suo livello oggetto è inferiore di almeno questo numero di punti a quello del pezzo equivalente che indossi.",
    ["Une plante à cueillir scintille quand tu t'en approches, terne de loin, vive à portée, grise si ta compétence est trop basse. Un seul objet brille à la fois. Utilise le ciblage d'interaction du jeu : l'objet le plus proche, jusqu'à environ 15 m, tout autour de toi. Pour cela Platyplus allume « Activer la touche d'interaction » et les icônes d'interaction des objets du monde du jeu, et les remet comme avant quand tu coupes toutes les étincelles ci-dessous. Pas d'étincelle pendant un combat."] = "Un'erba da raccogliere scintilla quando ti avvicini, spenta da lontano, vivida a portata, grigia se la tua abilità è troppo bassa. Brilla un solo oggetto alla volta. Usa il bersaglio di interazione del gioco: l'oggetto più vicino, fino a circa 15 m, tutto intorno a te. Per questo Platyplus attiva «Attiva il tasto di interazione» e le icone di interazione degli oggetti del mondo del gioco, e le rimette come prima quando disattivi tutti i bagliori qui sotto. Nessun bagliore durante il combattimento.",
    ["Une seule fenêtre pour tous les sacs"] = "Un'unica finestra per tutte le borse",
    ["Une seule touche pour tout : PNJ, coffres, plantes, cadavres à dépouiller, dialogues et quêtes."] = "Un solo tasto per tutto: PNG, forzieri, erbe, cadaveri da scuoiare, dialoghi e missioni.",
    ["Une touche pour interagir, parler et rendre les quêtes ; deux pour manger et boire."] = "Un tasto per interagire, parlare e consegnare le missioni; due per mangiare e bere.",
    ["Une touche pour parler aux PNJ, ramasser le butin et rendre les quêtes ; des alertes de combat, la menace lisible sur les mobs, la vente automatique, des fenêtres plus claires et bien plus. Tous les réglages sont dans la fenêtre de Platyplus (tu peux aussi taper /pp)."] = "Un tasto per parlare con i PNG, raccogliere il bottino e consegnare le missioni; avvisi di combattimento, la minaccia leggibile sui mob, la vendita automatica, finestre più chiare e molto altro. Tutte le impostazioni sono nella finestra di Platyplus (puoi anche digitare /pp).",
    ["Une touche pour presque tout"] = "Un tasto per quasi tutto",
    ["Utiliser l'objet de quête au bon endroit"] = "Usa l'oggetto di missione nel posto giusto",
    ["Utiliser la fenêtre de chat Platyplus"] = "Usa la finestra della chat Platyplus",
    ["Utiliser la fenêtre de quête Platyplus"] = "Usa la finestra delle missioni Platyplus",
    ["Utiliser la fenêtre du personnage Platyplus"] = "Usa la finestra del personaggio Platyplus",
    ["Utiliser les sacs Platyplus"] = "Usa le borse Platyplus",
    ["Valide automatiquement la fenêtre de confirmation de Blizzard quand tu ramasses un objet qui se lie à toi. Tu ne verras plus cette question."] = "Conferma automaticamente la finestra di conferma di Blizzard quando raccogli un oggetto che si vincola a te. Non vedrai più questa domanda.",
    ["Valider les quêtes et les dialogues"] = "Conferma missioni e dialoghi",
    ["Vend aussi les pièces d'équipement nettement moins bonnes que ce que tu portes déjà, selon les réglages ci-dessous. Les objets de « Ne jamais vendre » sont toujours épargnés. Vérifie d'abord avec l'aperçu en bas de page."] = "Vende anche i pezzi di equipaggiamento nettamente peggiori di ciò che indossi già, secondo le impostazioni qui sotto. Gli oggetti di «Non vendere mai» sono sempre risparmiati. Controlla prima con l'anteprima in fondo alla pagina.",
    ["Vend aussi les pièces « lié quand équipé » qui ne sont pas encore liées à toi. Elles peuvent parfois se vendre plus cher à l'hôtel des ventes, donc c'est coupé par défaut."] = "Vende anche i pezzi «vincolato all'equipaggiamento» non ancora vincolati a te. A volte possono vendersi a più alla casa d'aste, quindi è disattivato di default.",
    ["Vend tous les objets de qualité médiocre (gris) de tes sacs dès que tu ouvres un marchand."] = "Vende tutti gli oggetti di qualità scadente (grigi) delle tue borse appena apri un mercante.",
    ["Vend tout de suite ce qui est listé. Un marchand doit être ouvert."] = "Vende subito ciò che è elencato. Deve essere aperto un mercante.",
    ["Vendre"] = "Vendi",
    ["Vendre et réparer sans y penser"] = "Vendi e ripara senza pensarci",
    ["Vendre l'équipement inutile"] = "Vendi l'equipaggiamento inutile",
    ["Vendre les objets gris"] = "Vendi gli oggetti grigi",
    ["Vendre maintenant"] = "Vendi ora",
    ["Vends le superflu chez le marchand, le reste à l'hôtel des ventes ; réparation et courrier."] = "Vendi il superfluo al mercante, il resto alla casa d'aste; riparazione e posta.",
    ["Vendu"] = "Venduto",
    ["Vendu : %s"] = "Venduto: %s",
    ["Vente  %s"] = "Vendita  %s",
    ["Vente & HDV"] = "Vendite e aste",
