    ["Verrouillé (mode RPG) : bats le boss final du donjon précédent."] = "Bloccato (modalità GdR): sconfiggi il boss finale del dungeon precedente.",
    ["Vers le haut"] = "Verso l'alto",
    ["Vers le haut : chaque nouvelle ligne pousse les anciennes vers le haut. Vers le bas : l'inverse."] = "Verso l'alto: ogni nuova riga spinge le vecchie verso l'alto. Verso il basso: il contrario.",
    ["Version"] = "Versione",
    ["Vert : tout va bien, orange : ça se joue, rouge : danger. Les couleurs suivent ton rôle (tank ou DPS)."] = "Verde: tutto bene, arancione: si gioca sul filo, rosso: pericolo. I colori seguono il tuo ruolo (tank o DPS).",
    ["Victoires honorables au total"] = "Uccisioni onorevoli totali",
    ["Victoires honorables aujourd'hui"] = "Uccisioni onorevoli di oggi",
    ["Vider « jamais à l'HDV »"] = "Svuota «mai alla casa d'aste»",
