    ["Vie"] = "Salute",
    ["Vie : %d%%"] = "Salute: %d%%",
    ["Vise quelque chose (ou approche-toi) et appuie sur ta touche : Platyplus fait la bonne action."] = "Mira a qualcosa (o avvicinati) e premi il tuo tasto: Platyplus fa l'azione giusta.",
    ["Visible seulement quand ton groupe a un healer."] = "Visibile solo quando il tuo gruppo ha un guaritore.",
    ["Visite guidée"] = "Visita guidata",
    ["Vive"] = "Vivace",
    ["Vive : l'icône jaillit, des ondes dorées partent et un reflet la balaie. Douce : seulement le halo qui respire. Aucune : l'icône apparaît et reste fixe."] = "Vivace: l'icona sprizza, partono onde dorate e un riflesso la attraversa. Morbida: solo l'alone che respira. Nessuna: l'icona appare e resta ferma.",
