    ["allumées"] = "accese",
    ["anti-spam : %d message(s) masqué(s) depuis le chargement ; mots : %s. /pp spam ajouter MOT, /pp spam retirer MOT, /pp spam voir"] = "anti-spam: %d messaggio/i nascosto/i dal caricamento; parole: %s. /pp spam ajouter PAROLA, /pp spam retirer PAROLA, /pp spam voir",
    ["aperçu de l'alerte de proc, sorts surveillés (ta classe, ajoutés, ignorés) et leurs touches ; l'active ou la coupe"] = "anteprima dell'avviso di proc, incantesimi monitorati (la tua classe, aggiunti, ignorati) e i loro tasti; lo attiva o lo disattiva",
    ["aperçu de l'alerte de proc, sorts surveillés (ta classe, ajoutés, ignorés) et leurs touches | l'active ou la coupe"] = "anteprima dell'avviso di proc, incantesimi monitorati (la tua classe, aggiunti, ignorati) e i loro tasti | lo attiva o lo disattiva",
    ["aperçu de la barre de coups blancs ; la montre ou la cache"] = "anteprima della barra dei colpi bianchi; la mostra o la nasconde",
    ["aperçu de la barre de coups blancs | la montre ou la cache"] = "anteprima della barra dei colpi bianchi | la mostra o la nasconde",
    ["aperçu des cartes : tu aurais pris %s"] = "anteprima delle carte: avresti preso %s",
    ["aperçu des cartes de récompense de quête (objets d'exemple)"] = "anteprima delle carte di ricompensa delle missioni (oggetti di esempio)",
    ["applique les réglages du jeu recommandés | remet les anciens"] = "applica le impostazioni del gioco consigliate | rimette le vecchie",
